using System.IO;
using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
namespace PermanenciaWpf;
public partial class App:Application {
 private Mutex? mutex;
 protected override void OnStartup(StartupEventArgs e){base.OnStartup(e);ShutdownMode=ShutdownMode.OnExplicitShutdown;mutex=new Mutex(true,"Local\\ProjetoPermanenciaWPF",out bool first);if(!first){MessageBox.Show("O Permanência WPF já está aberto.");Shutdown();return;}DispatcherUnhandledException+=(_,a)=>{MessageBox.Show(a.Exception.Message,"Projeto Permanência");a.Handled=true;};
  var w=new MainWindow();MainWindow=w;w.Show();ShutdownMode=ShutdownMode.OnMainWindowClose;
 }
 protected override void OnExit(ExitEventArgs e){mutex?.Dispose();base.OnExit(e);}
}
public sealed class MainWindow:Window {
 public Database? Db;public JsonObject? User;private readonly ContentControl body=new();private readonly StackPanel nav=new();private readonly string configPath;private JsonObject config=new();
 public MainWindow(){Title="Projeto Permanência • 15º BPM";Width=1280;Height=850;MinWidth=980;MinHeight=660;WindowStartupLocation=WindowStartupLocation.CenterScreen;configPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PermanenciaWpf","config.json");
  var shell=new Grid();shell.ColumnDefinitions.Add(new(){Width=new GridLength(228)});shell.ColumnDefinitions.Add(new());nav.Background=UI.Ink;nav.Margin=new Thickness(0);shell.Children.Add(nav);Grid.SetColumn(body,1);shell.Children.Add(body);Content=shell;Closing+=(_,e)=>{if(Db!=null)try{Db.Backup();}catch(Exception ex){if(!UI.Confirm("Falha no backup automático: "+ex.Message+"\nFechar mesmo assim?"))e.Cancel=true;}};Closed+=(_,_)=>Db?.Dispose();Loaded+=(_,_)=>Start();
 }
 private void Menu(){nav.Children.Clear();var p=UI.Stack();p.Children.Add(UI.MenuCrest());var title=UI.Text("RELATÓRIO DIÁRIO",20,true);title.Foreground=System.Windows.Media.Brushes.White;p.Children.Add(title);var sub=UI.Text("15º BPM • Windows",12);sub.Foreground=System.Windows.Media.Brushes.LightGray;p.Children.Add(sub);if(User!=null){p.Children.Add(UI.Button("Início",Home));p.Children.Add(UI.Button("Relatórios diários",()=>History(null)));p.Children.Add(UI.Button("Cadastros",()=>Admin.Catalogs(this)));if(User.S("role")=="Administrador"){p.Children.Add(UI.Button("Auditoria",()=>Admin.Audit(this)));p.Children.Add(UI.Button("Banco e backups",()=>Admin.Bank(this)));}p.Children.Add(UI.Button("Sair da conta",()=>{Db?.Backup();User=null;Login();}));var t=UI.Text(User.S("name")+"\n"+User.S("role"),12);t.Foreground=System.Windows.Media.Brushes.LightGray;p.Children.Add(t);}nav.Children.Add(p);}
 public void Page(UIElement content){Menu();body.Content=content;}
 public void Start(){try{if(File.Exists(configPath)){config=JsonNode.Parse(File.ReadAllText(configPath))!.AsObject();Db=new Database(config.S("database"),backup:config.S("backup"));Login();}else Setup();}catch(Exception e){MessageBox.Show(e.Message,"Acesso ao banco");Setup();}}
 public void SaveConfig(){config["database"]=Db!.PathName;config["backup"]=Db.BackupDir;Directory.CreateDirectory(Path.GetDirectoryName(configPath)!);string temp=configPath+".tmp";File.WriteAllText(temp,config.ToJsonString());File.Move(temp,configPath,true);}
 private void Setup(){var p=UI.Stack();p.Children.Add(UI.Text("Bem-vindo ao Permanência",30,true));p.Children.Add(UI.Text("Configure um banco independente para esta versão WPF. A importação cria uma cópia e preserva o arquivo de origem."));var path=UI.Input(p,"Pasta dos dados",@"C:\Permanencia15BPM\Dados");p.Children.Add(UI.Button("Criar novo banco",()=>{string target=Path.Combine(path.Text,"Permanencia.db");if(UI.Confirm("Criar um novo banco em "+target+"?\nContas iniciais: ADMIN/admin e 15bpm/15bpm.")){Db=new Database(target,true);SaveConfig();Login();}},true));p.Children.Add(UI.Button("Importar cópia de banco ou backup existente",()=>{var open=new Microsoft.Win32.OpenFileDialog{Filter="Banco Permanência|*.db;*.bkp|Todos os arquivos|*.*"};if(open.ShowDialog(this)!=true)return;var save=new Microsoft.Win32.SaveFileDialog{FileName="Permanencia-WPF.db",Filter="Banco SQLite|*.db",InitialDirectory=path.Text};if(save.ShowDialog(this)!=true)return;Database.CopyDatabase(open.FileName,save.FileName);Db=new Database(save.FileName);SaveConfig();Login();}));Page(p);}
 public void Login(){User=null;var p=UI.Stack();p.MaxWidth=510;p.VerticalAlignment=VerticalAlignment.Center;p.Children.Add(UI.Crest(110));p.Children.Add(UI.Text("Acesse sua conta",28,true));p.Children.Add(UI.Text("Projeto Permanência • 15º Batalhão"));var login=UI.Input(p,"Usuário");p.Children.Add(UI.Text("Senha"));var password=new PasswordBox();p.Children.Add(password);var enter=UI.Button("Entrar",()=>{User=Db!.Authenticate(login.Text,password.Password);Home();},true);enter.IsDefault=true;p.Children.Add(enter);p.Children.Add(UI.Text(Db!.PathName,11));Page(p);login.Focus();}
 public void Home(){var p=UI.Stack();p.Children.Add(UI.Text("Selecione o quartel",30,true));p.Children.Add(UI.Text("Crie e consulte os Relatórios diários."));var cards=new WrapPanel();foreach(var (unit,title) in Rules.Units){var c=new StackPanel{Width=360};c.Children.Add(UI.Text(unit,21,true));c.Children.Add(UI.Text(title));c.Children.Add(UI.Button("Abrir quartel →",()=>History(unit),true));var card=UI.Card(c);card.Margin=new Thickness(0,8,16,8);cards.Children.Add(card);}p.Children.Add(cards);Page(new ScrollViewer{Content=p});}
 public void History(string? unit){var root=new DockPanel{Margin=new Thickness(28)};var h=new StackPanel();h.Children.Add(UI.Text(unit??"Todos os Relatórios diários",28,true));h.Children.Add(UI.Text("Histórico por data • edição disponível por 24 horas após o primeiro salvamento"));var actions=UI.Actions(h);if(unit!=null)actions.Children.Add(UI.Button("+ Novo Relatório diário",()=>new Editor(this,Db!.New(unit)).ShowDialog(),true));var filter=new WrapPanel();var from=new DatePicker{Width=145,Margin=new Thickness(0,4,10,8)};var to=new DatePicker{Width=145,Margin=new Thickness(0,4,10,8)};filter.Children.Add(UI.Text("De "));filter.Children.Add(from);filter.Children.Add(UI.Text("Até "));filter.Children.Add(to);var status=new ComboBox{Width=185,ItemsSource=new[]{"Todas as situações","EM PREENCHIMENTO","FINALIZADO"},SelectedIndex=0};filter.Children.Add(status);var cpu=new TextBox{Width=180,ToolTip="CPU que sai",Margin=new Thickness(10,4,0,8)};filter.Children.Add(cpu);h.Children.Add(filter);var grid=UI.Grid(("Data","date"),("Quartel","unit"),("CPU que sai","cpu"),("Situação","status"));var rowStyle=new Style(typeof(DataGridRow));var pending=new DataTrigger{Binding=new System.Windows.Data.Binding("[status]"),Value="EM PREENCHIMENTO"};pending.Setters.Add(new Setter(Control.BackgroundProperty,new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(255,244,179))));pending.Setters.Add(new Setter(Control.ForegroundProperty,System.Windows.Media.Brushes.Black));rowStyle.Triggers.Add(pending);var finalized=new DataTrigger{Binding=new System.Windows.Data.Binding("[status]"),Value="FINALIZADO"};finalized.Setters.Add(new Setter(Control.BackgroundProperty,new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(28,101,72))));finalized.Setters.Add(new Setter(Control.ForegroundProperty,System.Windows.Media.Brushes.White));rowStyle.Triggers.Add(finalized);grid.RowStyle=rowStyle;bool complete=false;
  Style ActionStyle(System.Windows.Media.Color baseColor,System.Windows.Media.Color hoverColor){var style=new Style(typeof(Button));style.Setters.Add(new Setter(Control.BackgroundProperty,new System.Windows.Media.SolidColorBrush(baseColor)));style.Setters.Add(new Setter(Control.ForegroundProperty,System.Windows.Media.Brushes.White));style.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0)));style.Setters.Add(new Setter(Control.WidthProperty,130d));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(12,5,12,5)));style.Setters.Add(new Setter(Control.FontWeightProperty,FontWeights.SemiBold));style.Setters.Add(new Setter(Control.CursorProperty,System.Windows.Input.Cursors.Hand));var template=new ControlTemplate(typeof(Button));var border=new FrameworkElementFactory(typeof(Border));border.SetValue(Border.CornerRadiusProperty,new CornerRadius(8));border.SetValue(Border.BackgroundProperty,new TemplateBindingExtension(Control.BackgroundProperty));var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(ContentPresenter.HorizontalAlignmentProperty,HorizontalAlignment.Center);content.SetValue(ContentPresenter.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(content);template.VisualTree=border;style.Setters.Add(new Setter(Control.TemplateProperty,template));var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(Control.BackgroundProperty,new System.Windows.Media.SolidColorBrush(hoverColor)));style.Triggers.Add(hover);if(User!.S("role")!="Administrador"){var locked=new DataTrigger{Binding=new System.Windows.Data.Binding("[status]"),Value="FINALIZADO"};locked.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Collapsed));style.Triggers.Add(locked);}return style;}var editStyle=ActionStyle(System.Windows.Media.Color.FromRgb(43,125,205),System.Windows.Media.Color.FromRgb(25,97,171));var deleteStyle=ActionStyle(System.Windows.Media.Color.FromRgb(181,62,62),System.Windows.Media.Color.FromRgb(143,42,42));FrameworkElementFactory ActionButton(string text,RoutedEventHandler handler,Style style){var button=new FrameworkElementFactory(typeof(Button));button.SetValue(Button.ContentProperty,text);button.SetValue(Button.MarginProperty,new Thickness(3,0,3,0));button.SetValue(Button.StyleProperty,style);button.AddHandler(Button.ClickEvent,handler);return button;}void EditRow(object sender){if((sender as FrameworkElement)?.DataContext is Dictionary<string,string> row){new Editor(this,Db!.Get(int.Parse(row["id"]))).ShowDialog();Refresh();}}void DeleteRow(object sender){if((sender as FrameworkElement)?.DataContext is Dictionary<string,string> row){var report=Db!.Get(int.Parse(row["id"]));if(UI.Confirm("Excluir o relatório de "+report.S("unit")+" / "+Rules.Date(report.S("day"))+"?")){Db.DeleteReport(User!,report);Refresh();}}}var panel=new FrameworkElementFactory(typeof(StackPanel));panel.SetValue(StackPanel.OrientationProperty,Orientation.Horizontal);panel.AppendChild(ActionButton("Editar",new RoutedEventHandler((sender,_)=>UI.Try(()=>EditRow(sender))),editStyle));panel.AppendChild(ActionButton("Excluir",new RoutedEventHandler((sender,_)=>UI.Try(()=>DeleteRow(sender))),deleteStyle));grid.Columns.Add(new DataGridTemplateColumn{Header="Ações",CellTemplate=new DataTemplate{VisualTree=panel},Width=DataGridLength.Auto});
 var hideEditWhenFinalized=new DataTrigger{Binding=new System.Windows.Data.Binding("[status]"),Value="FINALIZADO"};hideEditWhenFinalized.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Collapsed));editStyle.Triggers.Add(hideEditWhenFinalized);
 void Refresh(){var data=Db!.Reports(unit).Where(d=>(from.SelectedDate==null||DateTime.Parse(d.S("day"))>=from.SelectedDate)&&(to.SelectedDate==null||DateTime.Parse(d.S("day"))<=to.SelectedDate)&&(status.SelectedIndex==0||d.S("status")==UI.Value(status))&&Rules.Norm(Rules.Label(d["outgoing"])).Contains(Rules.Norm(cpu.Text)));if(!complete)data=data.Take(10);grid.ItemsSource=UI.Table(data.Select(d=>new JsonObject{["id"]=d.I("id"),["date"]=Rules.Date(d.S("day")),["unit"]=d.S("unit"),["cpu"]=Rules.Label(d["outgoing"]),["status"]=d.S("status")}));}
 actions.Children.Add(UI.Button("Consultar / atualizar",()=>{complete=true;Refresh();}));grid.MouseDoubleClick+=(_,_)=>UI.Try(()=>{new Editor(this,Db!.Get(UI.SelectedId(grid))).ShowDialog();Refresh();});DockPanel.SetDock(h,Dock.Top);root.Children.Add(h);root.Children.Add(grid);Page(root);Refresh();}
}
